/* ---------- small helpers ---------- */
function $(id){ return document.getElementById(id); }
function money(n){
  n = Math.round(Number(n)||0);
  return RUPEE + n.toLocaleString('en-IN');
}
function rnd(min,max){ return Math.round(min + Math.random()*(max-min)); }
function dayStart(d){ var x=new Date(d); x.setHours(0,0,0,0); return x; }
function daysAgo(n){ var x=dayStart(new Date()); x.setDate(x.getDate()-n); return x; }
function fmtDate(ts){
  var d=new Date(ts), t=dayStart(new Date()).getTime(), dd=dayStart(d).getTime();
  if(dd===t) return 'Today';
  if(dd===daysAgo(1).getTime()) return 'Yesterday';
  return d.getDate()+' '+['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][d.getMonth()];
}
function esc(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;')
                  .replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function catNames(){ return CATS.map(function(c){return c.name;}); }
function findCat(name){
  for(var i=0;i<CATS.length;i++){ if(CATS[i].name===name) return CATS[i]; }
  return null;
}
function showErr(id,msg){ var e=$(id); if(!e) return; if(msg) e.textContent=msg; e.classList.add('show'); }
function hideErr(id){ var e=$(id); if(e) e.classList.remove('show'); }
function hideAllErrs(){
  var list=document.querySelectorAll('.err');
  for(var i=0;i<list.length;i++) list[i].classList.remove('show');
}
function toast(msg){
  var t=$('toast'); t.textContent=msg; t.classList.add('show');
  clearTimeout(window._tt);
  window._tt=setTimeout(function(){ t.classList.remove('show'); },2200);
}

/* ---------- transaction queries ---------- */
function txnsSince(days){
  var cut = daysAgo(days-1).getTime();
  return TXNS.filter(function(t){ return t.ts >= cut; });
}
function txnsBetween(fromDaysAgo, toDaysAgo){
  var a = daysAgo(fromDaysAgo).getTime(), b = daysAgo(toDaysAgo).getTime();
  return TXNS.filter(function(t){ return t.ts >= a && t.ts < b; });
}
function sum(list){ return list.reduce(function(a,t){ return a+t.amt; },0); }
function byCat(list,name){ return list.filter(function(t){ return t.cat===name; }); }
function byMerchant(list,name){ return list.filter(function(t){ return t.merchant===name; }); }
function periodDef(){
  for(var i=0;i<PERIODS.length;i++){ if(PERIODS[i].key===state.period) return PERIODS[i]; }
  return PERIODS[0];
}

/* ---------- seeding ---------- */
function seedCategories(){
  CATS = DEFAULT_CATS.map(function(n){
    var daily = n==='Food' ? 220 : n==='Groceries' ? 180 : n==='Necessities' ? 200
              : n==='Transport' ? 100 : n==='Snacks/Beverages' ? 90
              : n==='Stationery' ? 60 : 120;
    return {name:n, daily:daily, weekly:daily*7};
  });
}
function seedTransactions(){
  TXNS = [];
  var id=1;
  for(var d=34; d>=0; d--){
    var date = daysAgo(d);
    for(var m=0;m<MERCHANTS.length;m++){
      var mm = MERCHANTS[m];
      var chance = mm.perWeek/7;
      var times = Math.floor(chance) + (Math.random() < (chance % 1) ? 1 : 0);
      for(var k=0;k<times;k++){
        var ts = new Date(date);
        ts.setHours(rnd(8,21), rnd(0,59), 0, 0);
        TXNS.push({
          id:id++, merchant:mm.name, cat:mm.cat,
          amt:rnd(mm.min,mm.max), ts:ts.getTime(),
          source: Math.random()<0.85 ? 'UPI' : 'Manual'
        });
      }
    }
  }
  TXNS.sort(function(a,b){ return b.ts-a.ts; });
  state.balance = rnd(8000,16000);
}
function seedGoals(){
  GOALS = [
    {id:1,name:'Motorcycle down payment',target:25000,saved:rnd(6000,11000),by:'March',hist:[]},
    {id:2,name:'Trip to Goa',target:8000,saved:rnd(1500,4000),by:'December',hist:[]}
  ];
  GOALS.forEach(function(g){
    g.hist=[{amt:Math.round(g.saved*0.6),ts:daysAgo(21).getTime()},
            {amt:g.saved-Math.round(g.saved*0.6),ts:daysAgo(6).getTime()}];
  });
}
function seedSubs(){
  SUBS = [
    {id:1,name:'Coursera',amt:2500,day:14,cat:'Necessities',
     note:'Auto-debits every month. Easy to forget it is still running.'},
    {id:2,name:'Spotify',amt:119,day:3,cat:'Entertainment',note:''},
    {id:3,name:'Cloud storage',amt:130,day:22,cat:'Necessities',note:''}
  ];
}

/* ---------- navigation ---------- */
var TAB_FRAMES = ['home','categories','insight','savings','settings'];
var STEP_OF = {method:1, upiSetup:1, onbCategories:2, pin:3, permissions:4};

function go(name){
  var frames = document.querySelectorAll('.frame');
  for(var i=0;i<frames.length;i++) frames[i].classList.remove('active');
  var f = document.querySelector('.frame[data-frame="'+name+'"]');
  if(!f) return;
  f.classList.add('active');
  f.scrollTop = 0;
  state.current = name;
  closeSheet();
  hideAllErrs();

  var onTab = TAB_FRAMES.indexOf(name) !== -1;
  document.body.classList.toggle('with-nav', onTab);
  var tabs = document.querySelectorAll('.tab');
  for(var j=0;j<tabs.length;j++){
    tabs[j].classList.toggle('on', tabs[j].getAttribute('data-tab')===name);
  }
  renderDots(name);
  renderAll();
}

function renderDots(name){
  var step = STEP_OF[name];
  var box = $('dots-'+name);
  if(!box) return;
  var html='';
  for(var i=1;i<=4;i++) html += '<i class="'+(i===step?'on':'')+'"></i>';
  box.innerHTML = html;
}

/* ---------- sheets ---------- */
function openSheet(name){
  var scrim = $('scrim');
  var sheets = document.querySelectorAll('.sheet');
  for(var i=0;i<sheets.length;i++){
    sheets[i].style.display = (sheets[i].getAttribute('data-sheet')===name) ? 'block' : 'none';
  }
  scrim.classList.add('show');
  if(name==='periodSheet') renderPeriodOptions();
  if(name==='budgetSheet') openBudgetSheet();
  if(name==='editCatsSheet') renderSheetCats();
  if(name==='quickCatSheet') renderQuickCats();
  if(name==='accountSheet') renderSheetAccounts();
  if(name==='trackingSheet') renderTrackingSheet();
  if(name==='savingsSheet') renderSavingsSheet();
}
function closeSheet(){
  $('scrim').classList.remove('show');
  var sheets = document.querySelectorAll('.sheet');
  for(var i=0;i<sheets.length;i++) sheets[i].style.display='none';
}
function closeSheetIfScrim(e){ if(e.target && e.target.id==='scrim') closeSheet(); }

/* =====================================================================
   ONBOARDING
   ===================================================================== */
function chooseTracking(mode){
  state.tracking = mode;
  if(mode==='upi'){ go('upiSetup'); } else { go('onbCategories'); }
}
function backFromCategories(){ go(state.tracking==='upi' ? 'upiSetup' : 'method'); }

function validUpi(v){ return /^[\w.\-]{2,}@[a-z]{2,}$/i.test(v); }

function addUpi(){
  var el=$('upi-input'), v=el.value.trim();
  if(!validUpi(v)){ showErr('err-upi'); return; }
  if(ACCOUNTS.indexOf(v)===-1) ACCOUNTS.push(v);
  el.value=''; hideErr('err-upi'); renderAll();
}
function addUpiFromSheet(){
  var el=$('sheet-upi-input'), v=el.value.trim();
  if(!validUpi(v)){ showErr('err-sheet-upi'); return; }
  if(ACCOUNTS.indexOf(v)===-1) ACCOUNTS.push(v);
  el.value=''; hideErr('err-sheet-upi'); renderAll(); toast('Account added');
}
function removeAccount(v){
  ACCOUNTS = ACCOUNTS.filter(function(a){ return a!==v; });
  renderAll();
}
function finishUpi(){
  if(!ACCOUNTS.length){ showErr('err-upi','Add at least one UPI ID to continue'); return; }
  go('onbCategories');
}
function renderUpiList(){
  var box=$('upi-list');
  if(box){
    box.innerHTML = ACCOUNTS.length
      ? ACCOUNTS.map(function(a){
          return '<button class="pill" onclick="removeAccount(\''+esc(a)+'\')">'
               + esc(a) + '<span class="x">&times;</span></button>';
        }).join('')
      : '<span class="micro">No accounts yet &mdash; add one above.</span>';
  }
}
function renderSheetAccounts(){
  var box=$('sheet-accounts');
  if(!box) return;
  box.innerHTML = ACCOUNTS.length
    ? ACCOUNTS.map(function(a){
        return '<button class="pill" onclick="removeAccount(\''+esc(a)+'\')">'
             + esc(a) + '<span class="x">&times;</span></button>';
      }).join('')
    : '<span class="micro">No accounts connected.</span>';
}

/* categories during onboarding */
function addCat(name){
  name = String(name||'').trim();
  if(!name) return false;
  if(findCat(name)) return false;
  CATS.push({name:name, daily:80, weekly:560});
  return true;
}
function removeCat(name){
  CATS = CATS.filter(function(c){ return c.name!==name; });
  TXNS.forEach(function(t){ if(t.cat===name) t.cat='Other'; });
  if(!findCat('Other') && TXNS.some(function(t){ return t.cat==='Other'; })){
    CATS.push({name:'Other',daily:60,weekly:420});
  }
  renderAll();
}
function addTypedCat(){
  var el=$('cat-input');
  if(addCat(el.value)){ el.value=''; hideErr('err-cat'); renderAll(); }
  else { el.value=''; }
}
function addCatFromSheet(){
  var el=$('sheet-cat-input');
  if(addCat(el.value)){ el.value=''; renderAll(); toast('Category added'); }
  else { el.value=''; }
}
function addRecommended(name){ if(addCat(name)) renderAll(); }
function finishCategories(){
  if(!CATS.length){ showErr('err-cat'); return; }
  go('pin');
}
function renderChosenCats(){
  var html = CATS.map(function(c){
    return '<button class="pill" onclick="removeCat(\''+esc(c.name)+'\')">'
         + esc(c.name) + '<span class="x">&times;</span></button>';
  }).join('');
  var a=$('chosen-cats'); if(a) a.innerHTML = html || '<span class="micro">None chosen yet.</span>';
  var b=$('sheet-chosen-cats'); if(b) b.innerHTML = html || '<span class="micro">None yet.</span>';
}
function renderRecommended(){
  var box=$('rec-list'); if(!box) return;
  var q = ($('rec-search') ? $('rec-search').value : '').trim().toLowerCase();
  var pool = RECOMMENDED.concat(DEFAULT_CATS).filter(function(n){
    return !findCat(n) && (!q || n.toLowerCase().indexOf(q)!==-1);
  });
  box.innerHTML = pool.length
    ? pool.map(function(n){
        return '<button class="pill" onclick="addRecommended(\''+esc(n)+'\')">+ '+esc(n)+'</button>';
      }).join('')
    : '<span class="micro">Nothing left to add.</span>';
}

function submitPin(){
  var a=$('pin1').value.trim(), b=$('pin2').value.trim();
  if(!/^\d{4}$/.test(a) || a!==b){ showErr('err-pin'); return; }
  state.pin=a; hideErr('err-pin'); go('permissions');
}
function changePin(){
  var a=$('pc1').value.trim(), b=$('pc2').value.trim();
  if(!/^\d{4}$/.test(a) || a!==b){ showErr('err-pc'); return; }
  state.pin=a; $('pc1').value=''; $('pc2').value='';
  hideErr('err-pc'); toast('PIN updated'); go('settings');
}
function togglePerm(id){
  state.perms[id] = !state.perms[id];
  renderPerms();
}
function mirrorPerm(id){ togglePerm(id); }
function renderPerms(){
  Object.keys(state.perms).forEach(function(id){
    var el=$(id); if(el) el.classList.toggle('on', !!state.perms[id]);
    var el2=$(id+'-2'); if(el2) el2.classList.toggle('on', !!state.perms[id]);
  });
}

function enterApp(){
  if(!TXNS.length) seedTransactions();
  go('home');
}

function renderAllSet(){
  var sub=$('allset-sub');
  if(sub){
    sub.textContent = state.tracking==='upi'
      ? "We'll log your UPI spends automatically and show you where the money goes — starting today."
      : "Add spends as you go and Trickle will show you where the money goes — starting today.";
  }
  var panel=$('allset-accounts-panel');
  if(panel) panel.style.display = (state.tracking==='upi' && ACCOUNTS.length) ? 'block' : 'none';
  var acc=$('allset-accounts');
  if(acc) acc.innerHTML = ACCOUNTS.map(function(a){
    return '<span class="pill" style="cursor:default">'+esc(a)+'</span>'; }).join('');
  var cats=$('allset-cats');
  if(cats) cats.innerHTML = CATS.map(function(c){
    return '<span class="pill" style="cursor:default">'+esc(c.name)+'</span>'; }).join('');
}

/* =====================================================================
   HOME
   ===================================================================== */
function toggleBalance(){
  state.balanceHidden = !state.balanceHidden;
  renderHome();
}
function deltaHtml(now, prev){
  if(!prev) return '';
  var pct = Math.round(((now-prev)/prev)*100);
  if(pct===0) return '<span class="delta">level</span>';
  var up = pct>0;
  return '<span class="delta">'+(up?'&#9650;':'&#9660;')+' '+Math.abs(pct)+'%</span>';
}
function accumulationPatterns(){
  var week = txnsSince(7), map = {};
  week.forEach(function(t){
    if(!map[t.merchant]) map[t.merchant]={merchant:t.merchant,cat:t.cat,count:0,total:0};
    map[t.merchant].count++; map[t.merchant].total+=t.amt;
  });
  return Object.keys(map).map(function(k){ return map[k]; })
    .filter(function(p){ return p.count>=2; })
    .sort(function(a,b){ return b.total-a.total; });
}
function renderHome(){
  var todayTot = sum(txnsSince(1));
  var yestTot  = sum(txnsBetween(1,0));
  var weekTot  = sum(txnsSince(7));
  var prevWeek = sum(txnsBetween(13,6));

  $('home-weekly').textContent = money(weekTot);
  $('home-weekly-delta').innerHTML = deltaHtml(weekTot, prevWeek);
  $('home-daily').textContent = money(todayTot);
  $('home-daily-delta').innerHTML = deltaHtml(todayTot, yestTot);
  $('home-balance').textContent = 'Balance : ' + (state.balanceHidden ? '•••••' : money(state.balance));
  var slash=$('eye-slash'); if(slash) slash.style.display = state.balanceHidden ? 'block' : 'none';
  $('home-account').textContent = 'Account : ' + (ACCOUNTS[0] || 'manual entry');

  var upiMode = state.tracking!=='manual';
  $('home-tiles').style.display = upiMode ? 'flex' : 'none';
  $('home-manual').style.display = upiMode ? 'none' : 'block';
  var tiles = $('home-tiles').children;
  tiles[0].style.display = state.perms['perm-camera'] ? 'flex' : 'none';
  tiles[1].style.display = state.perms['perm-contacts'] ? 'flex' : 'none';

  var pats = accumulationPatterns().slice(0,3);
  $('home-trends').innerHTML = pats.length ? pats.map(function(p){
    return '<div class="trend-row"><span class="tr-name">'+esc(p.merchant)+' :</span>'
         + '<span class="tr-count">'+p.count+'x this week</span>'
         + '<span class="tr-amt">'+money(p.total)+'</span></div>';
  }).join('') : '<p class="micro">Nothing repeating yet this week.</p>';

  var recent = TXNS.slice(0,5);
  $('home-txns').innerHTML = recent.length ? recent.map(function(t){
    return '<div class="txn-row" style="cursor:inherit"><span class="t-merch">'+esc(t.merchant)+'</span>'
         + '<span class="t-cat">'+esc(t.cat)+'</span>'
         + '<span class="t-amt">'+money(t.amt)+'</span></div>';
  }).join('') : '<p class="micro">No transactions yet.</p>';
}

/* accumulation screens */
function renderAccumulation(){
  var box=$('accum-list'); if(!box) return;
  var pats = accumulationPatterns();
  box.innerHTML = pats.length ? pats.map(function(p){
    return '<button class="card-btn" onclick="openPattern(\''+esc(p.merchant)+'\')">'
      + '<div class="between"><span style="font-size:15px;font-weight:700">'+esc(p.merchant)+'</span>'
      + '<span style="font-size:15px;font-weight:700">'+money(p.total)+'</span></div>'
      + '<div class="between" style="margin-top:5px">'
      + '<span class="micro">'+esc(p.cat)+' &middot; '+p.count+' purchases this week</span>'
      + '<span class="micro">avg '+money(p.total/p.count)+'</span></div>'
      + '</button>';
  }).join('') : '<p class="empty-note">No repeat purchases this week.</p>';
}
function openPattern(merchant){
  state.selectedMerchant = merchant;
  go('accumulationDetail');
}
function renderAccumulationDetail(){
  if(!state.selectedMerchant) return;
  var list = byMerchant(txnsSince(7), state.selectedMerchant);
  var total = sum(list);
  $('accd-title').textContent = state.selectedMerchant;
  $('accd-total').textContent = money(total);
  $('accd-count').textContent = list.length;
  $('accd-avg').textContent = money(list.length ? total/list.length : 0);
  $('accd-list').innerHTML = list.map(function(t){
    return '<button class="txn-row" onclick="openTxn('+t.id+')">'
      + '<span class="t-merch">'+fmtDate(t.ts)+'</span>'
      + '<span class="t-cat">'+new Date(t.ts).getHours()+':00</span>'
      + '<span class="t-amt">'+money(t.amt)+'</span></button>';
  }).join('') || '<p class="empty-note">Nothing this week.</p>';
}

/* =====================================================================
   TRANSACTIONS
   ===================================================================== */
function setTxnFilter(name){ state.catFilter=name; renderTxnList(); }
function renderTxnList(){
  var box=$('txn-list'); if(!box) return;
  var filters=$('txn-filters');
  if(filters){
    var opts=['All'].concat(catNames());
    filters.innerHTML = opts.map(function(n){
      return '<button class="pill'+(state.catFilter===n?' on':'')
           + '" onclick="setTxnFilter(\''+esc(n)+'\')">'+esc(n)+'</button>';
    }).join('');
  }
  var q = ($('txn-search') ? $('txn-search').value : '').trim().toLowerCase();
  var list = TXNS.filter(function(t){
    if(state.catFilter!=='All' && t.cat!==state.catFilter) return false;
    if(q && (t.merchant+' '+t.cat).toLowerCase().indexOf(q)===-1) return false;
    return true;
  }).slice(0,60);

  if(!list.length){ box.innerHTML='<p class="empty-note">No transactions match.</p>'; return; }
  var html='', lastDay='';
  list.forEach(function(t){
    var d = fmtDate(t.ts);
    if(d!==lastDay){
      html += '<div class="micro" style="padding:14px 2px 5px;border-bottom:1px solid var(--line)">'+d+'</div>';
      lastDay=d;
    }
    html += '<button class="txn-row" onclick="openTxn('+t.id+')">'
         + '<span class="t-merch">'+esc(t.merchant)+'</span>'
         + '<span class="t-cat">'+esc(t.cat)+'</span>'
         + '<span class="t-src">'+t.source+'</span>'
         + '<span class="t-amt">'+money(t.amt)+'</span></button>';
  });
  box.innerHTML = html;
}
function openTxn(id){
  var t = TXNS.filter(function(x){ return x.id===id; })[0];
  if(!t) return;
  state.selectedTxn = id;
  state.selectedTxnCat = t.cat;
  go('transactionDetail');
}
function pickTxnCat(name){ state.selectedTxnCat=name; renderTxnDetail(); }
function renderTxnDetail(){
  var t = TXNS.filter(function(x){ return x.id===state.selectedTxn; })[0];
  if(!t) return;
  $('td-amt').textContent = money(t.amt);
  $('td-merch').textContent = t.merchant;
  $('td-date').textContent = fmtDate(t.ts);
  $('td-src').textContent = t.source==='UPI' ? 'UPI auto-log' : 'You, manually';
  $('td-cats').innerHTML = catNames().map(function(n){
    return '<button class="pill'+(state.selectedTxnCat===n?' on':'')
         + '" onclick="pickTxnCat(\''+esc(n)+'\')">'+esc(n)+'</button>';
  }).join('');
}
function saveTxnCategory(){
  var t = TXNS.filter(function(x){ return x.id===state.selectedTxn; })[0];
  if(t && state.selectedTxnCat){ t.cat = state.selectedTxnCat; }
  toast('Category updated');
  go('transactions');
}

/* manual entry */
function pickManualCat(name){ state.manualCat=name; renderManualCats(); }
function renderManualCats(){
  var box=$('me-cats'); if(!box) return;
  box.innerHTML = catNames().map(function(n){
    return '<button class="pill'+(state.manualCat===n?' on':'')
         + '" onclick="pickManualCat(\''+esc(n)+'\')">'+esc(n)+'</button>';
  }).join('');
}
function submitManual(){
  var amt = parseFloat($('me-amount').value);
  var merch = $('me-merchant').value.trim() || 'Cash spend';
  if(!(amt>0) || !state.manualCat){ showErr('err-me'); return; }
  TXNS.unshift({id:(TXNS.length?Math.max.apply(null,TXNS.map(function(t){return t.id;}))+1:1),
    merchant:merch, cat:state.manualCat, amt:Math.round(amt),
    ts:Date.now(), source:'Manual'});
  state.balance = Math.max(0, state.balance - Math.round(amt));
  $('me-amount').value=''; $('me-merchant').value=''; state.manualCat=null;
  hideErr('err-me');
  toast('Added ' + money(amt));
  go('home');
}

/* =====================================================================
   PAYMENT FLOW  (Scan / Pay Anyone / Bank Transfer -> Amount -> Friction -> Confirm)
   ===================================================================== */
function renderQuickCats(){
  var box=$('quick-cat-list'); if(!box) return;
  box.innerHTML = catNames().map(function(n){
    return '<button class="pill'+(state.scanCat===n?' on':'')
         + '" onclick="setScanCat(\''+esc(n)+'\')">'+esc(n)+'</button>';
  }).join('');
}
function setScanCat(n){
  state.scanCat=n;
  var el=$('scan-cat'); if(el) el.textContent=n;
  renderQuickCats();
  closeSheet();
}
function renderContacts(){
  var box=$('contact-list'); if(!box) return;
  var q = ($('contact-search') ? $('contact-search').value : '').trim().toLowerCase();
  var list = CONTACTS.filter(function(c){ return !q || c.toLowerCase().indexOf(q)!==-1; });
  box.innerHTML = list.length ? list.map(function(c){
    return '<button class="row-link" onclick="startPayment(\'contact\',\''+esc(c)+'\')">'
      + '<span class="avatar" style="width:32px;height:32px;cursor:inherit">'
      + '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="var(--ink)" stroke-width="1.7">'
      + '<circle cx="12" cy="8.5" r="3.6"/><path d="M4.8 20c.8-3.8 3.8-5.6 7.2-5.6s6.4 1.8 7.2 5.6"/></svg></span>'
      + '<span class="rl-main">'+esc(c)+'</span>'
      + '<span class="rl-val">Pay</span></button>';
  }).join('') : '<p class="empty-note">No contacts match.</p>';
}
function submitBank(){
  var a=$('bank-acct').value.trim(), i=$('bank-ifsc').value.trim();
  if(a.length<6 || i.length<4){ showErr('err-bank'); return; }
  hideErr('err-bank');
  startPayment('bank','A/c •••'+a.slice(-4));
}
function startPayment(source, who){
  state.pending = {
    to: who || (source==='scan' ? 'Scanned QR merchant' : 'Someone'),
    cat: source==='scan' ? state.scanCat : 'Food',
    amt: 0
  };
  state.payCat = state.pending.cat;
  $('pay-to').textContent = state.pending.to;
  $('pay-amount').value='';
  go('payAmount');
}
function pickPayCat(n){ state.payCat=n; if(state.pending) state.pending.cat=n; renderPayCats(); }
function renderPayCats(){
  var box=$('pay-cats'); if(!box) return;
  box.innerHTML = catNames().map(function(n){
    return '<button class="pill'+(state.payCat===n?' on':'')
         + '" onclick="pickPayCat(\''+esc(n)+'\')">'+esc(n)+'</button>';
  }).join('');
}
function checkPayment(){
  var amt = parseFloat($('pay-amount').value);
  if(!(amt>0)){ showErr('err-pay'); return; }
  hideErr('err-pay');
  state.pending.amt = Math.round(amt);
  renderFriction();
  openSheet('frictionSheet');
}
function renderFriction(){
  var p = state.pending; if(!p) return;
  var cat = findCat(p.cat) || {name:p.cat, weekly:560, daily:80};
  var spent = sum(byCat(txnsSince(7), p.cat));
  var budget = cat.weekly || 560;
  var after = state.balance - p.amt;

  $('fr-balance').textContent = money(after);
  $('fr-cat-title').textContent = cat.name + ' (Weekly)';

  var total = Math.max(budget, spent + p.amt);
  var wSpent = (spent/total)*100;
  var wThis  = (p.amt/total)*100;
  var wLeft  = Math.max(0, 100 - wSpent - wThis);
  $('fr-spent').style.width = wSpent.toFixed(1)+'%';
  $('fr-this').style.width  = wThis.toFixed(1)+'%';
  $('fr-left').style.width  = wLeft.toFixed(1)+'%';

  $('fr-spent-lbl').innerHTML = 'Total Spent : ' + money(spent + p.amt);
  $('fr-budget-lbl').innerHTML = 'Total budget : ' + money(budget);
  $('fr-day').textContent  = 'Day : '  + byCat(txnsSince(1), p.cat).length;
  $('fr-week').textContent = 'Week : ' + byCat(txnsSince(7), p.cat).length;

  var left = budget - spent - p.amt;
  var note = $('fr-note');
  if(left >= 0){
    note.textContent = 'After this, ' + money(left) + ' left in ' + cat.name + ' for the rest of the week.';
  } else {
    note.textContent = 'This takes ' + cat.name + ' ' + money(-left)
      + ' past your weekly budget. Still your call.';
  }
}
function confirmPayment(){
  var p = state.pending; if(!p) return;
  TXNS.unshift({id:(TXNS.length?Math.max.apply(null,TXNS.map(function(t){return t.id;}))+1:1),
    merchant:p.to, cat:p.cat, amt:p.amt, ts:Date.now(), source:'UPI'});
  state.balance = Math.max(0, state.balance - p.amt);
  closeSheet();
  $('confirm-line').textContent = money(p.amt) + ' to ' + p.to;
  var g = GOALS[0];
  $('peek-sub').textContent = g
    ? 'Round up to ' + g.name + '? ' + money(g.saved) + ' of ' + money(g.target) + ' saved'
    : 'Start a savings goal';
  go('payConfirm');
}
function renderSavingsSheet(){
  var p = state.pending;
  var spare = p ? Math.max(10, Math.ceil(p.amt/50)*50 - p.amt) : 50;
  if(spare < 10) spare = 10;
  var line=$('ss-line');
  if(line) line.textContent = 'Round this payment up and move ' + money(spare) + ' into a goal.';
  var box=$('ss-goals'); if(!box) return;
  box.innerHTML = GOALS.length ? GOALS.map(function(g){
    var pct = Math.min(100, (g.saved/g.target)*100);
    return '<button class="goal-card" onclick="quickSave('+g.id+','+spare+')">'
      + '<div class="between"><span style="font-weight:700">'+esc(g.name)+'</span>'
      + '<span style="font-size:12px">+'+money(spare)+'</span></div>'
      + '<div class="bar" style="margin-top:10px"><i style="width:'+pct.toFixed(1)+'%"></i></div>'
      + '<div class="micro" style="margin-top:6px">'+money(g.saved)+' of '+money(g.target)+'</div>'
      + '</button>';
  }).join('') : '<p class="empty-note">No goals yet.</p>';
}
function quickSave(id, amt){
  var g = GOALS.filter(function(x){ return x.id===id; })[0];
  if(!g) return;
  g.saved += amt;
  g.hist.unshift({amt:amt, ts:Date.now()});
  state.balance = Math.max(0, state.balance - amt);
  closeSheet();
  if(g.saved >= g.target){
    state.selectedGoal = g.id;
    $('gr-line').textContent = g.name + ' is fully funded at ' + money(g.target) + '.';
    go('goalReached');
  } else {
    toast(money(amt) + ' moved to ' + g.name);
    renderAll();
  }
}

