function renderPeriodOptions(){
  var box=$('period-options'); if(!box) return;
  box.innerHTML = PERIODS.map(function(p){
    return '<button class="field" style="justify-content:space-between;cursor:pointer" '
      + 'onclick="setPeriod(\''+p.key+'\')"><span>'+p.label+'</span><span style="font-size:13px">'
      + (state.period===p.key ? '&#10003;' : '') + '</span></button>';
  }).join('');
}
function setPeriod(k){ state.period=k; closeSheet(); renderAll(); }

function catSpend(name, days){ return sum(byCat(txnsSince(days), name)); }
function catBudget(cat, days){
  if(days===1) return cat.daily;
  if(days===7) return cat.weekly;
  return Math.round(cat.daily*30);
}
function renderCategories(){
  var pd = periodDef();
  $('cat-period-label').textContent = pd.label;

  var rows = CATS.map(function(c){
    return {name:c.name, amt:catSpend(c.name, pd.days),
            prev: sum(byCat(txnsBetween(pd.days*2-1, pd.days-1), c.name))};
  }).sort(function(a,b){ return b.amt-a.amt; });

  var total = rows.reduce(function(a,r){ return a+r.amt; },0);
  drawDonut(rows, total);

  $('cat-legend').innerHTML = rows.slice(0,8).map(function(r,i){
    return '<span><i style="background:'+shade(i,rows.length)+'"></i>'+esc(r.name)+'</span>';
  }).join('');

  $('cat-rows').innerHTML = rows.map(function(r){
    return '<button class="cat-row" onclick="openCategory(\''+esc(r.name)+'\')">'
      + '<span class="cr-name">'+esc(r.name)+'</span>'
      + '<span class="cr-amt">'+money(r.amt)+'</span>'
      + '<span class="cr-delta">'+deltaHtml(r.amt, r.prev)+'</span>'
      + '</button>';
  }).join('');
}
function shade(i,n){
  var palette=['#ff7a45','#ffd23f','#8ab4ff','#7ee787','#ff8fb1','#c792ea','#5fd0d0','#f4a261'];
  return palette[i % palette.length];
}
function drawDonut(rows, total){
  var svg=$('donut'); if(!svg) return;
  var cx=125, cy=125, r=88, w=34;
  if(!total){
    svg.innerHTML = '<circle cx="125" cy="125" r="88" fill="none" stroke="#e4e4e4" stroke-width="34"/>'
      + '<text x="125" y="130" text-anchor="middle" font-size="13" fill="#555555">No spend yet</text>';
    return;
  }
  var html='', angle=-Math.PI/2;
  rows.forEach(function(row,i){
    if(!row.amt) return;
    var slice = (row.amt/total)*Math.PI*2;
    var a1=angle, a2=angle+slice;
    var large = slice>Math.PI ? 1 : 0;
    var x1=cx+r*Math.cos(a1), y1=cy+r*Math.sin(a1);
    var x2=cx+r*Math.cos(a2), y2=cy+r*Math.sin(a2);
    html += '<path d="M '+x1.toFixed(2)+' '+y1.toFixed(2)
         +  ' A '+r+' '+r+' 0 '+large+' 1 '+x2.toFixed(2)+' '+y2.toFixed(2)+'" '
         +  'fill="none" stroke="'+shade(i,rows.length)+'" stroke-width="'+w+'"/>';
    angle=a2;
  });
  html += '<text x="125" y="119" text-anchor="middle" font-size="11" fill="#555555">'
       +  periodDef().sub + '</text>'
       +  '<text x="125" y="141" text-anchor="middle" font-size="19" font-weight="700" fill="#ffffff">'
       +  money(total) + '</text>';
  svg.innerHTML = html;
}
function openCategory(name){ state.selectedCategory=name; go('categoryDetail'); }
function renderCategoryDetail(){
  var name = state.selectedCategory; if(!name) return;
  var cat = findCat(name) || {name:name, daily:80, weekly:560};
  var pd = periodDef();
  var spent = catSpend(name, pd.days);
  var budget = catBudget(cat, pd.days);
  var pct = budget ? Math.min(100,(spent/budget)*100) : 0;

  $('cd-title').textContent = name;
  $('cd-spent').textContent = money(spent);
  $('cd-period').textContent = pd.sub;
  $('cd-fill').style.width = pct.toFixed(1)+'%';
  $('cd-budget-line').textContent = 'Budget ' + money(budget) + ' ' + pd.sub;
  $('cd-left-line').textContent = (budget-spent >= 0)
    ? money(budget-spent) + ' left' : money(spent-budget) + ' over';

  var list = byCat(txnsSince(pd.days), name).slice(0,25);
  $('cd-txns').innerHTML = list.length ? list.map(function(t){
    return '<button class="txn-row" onclick="openTxn('+t.id+')">'
      + '<span class="t-merch">'+esc(t.merchant)+'</span>'
      + '<span class="t-cat">'+fmtDate(t.ts)+'</span>'
      + '<span class="t-amt">'+money(t.amt)+'</span></button>';
  }).join('') : '<p class="empty-note">Nothing in this category yet.</p>';
}
function openBudgetFor(){
  state.budgetSheetCat = state.selectedCategory || 'Food';
  openSheet('budgetSheet');
}
function openBudgetSheet(){
  if(!findCat(state.budgetSheetCat)) state.budgetSheetCat = CATS.length ? CATS[0].name : 'Food';
  var c = findCat(state.budgetSheetCat);
  $('budget-cat-name').textContent = state.budgetSheetCat;
  if(c){ $('budget-daily').value = c.daily; $('budget-weekly').value = c.weekly; }
}
function cycleBudgetCat(){
  var names = catNames();
  if(!names.length) return;
  var i = names.indexOf(state.budgetSheetCat);
  state.budgetSheetCat = names[(i+1) % names.length];
  openBudgetSheet();
}
function budgetDailyChanged(){
  var d = parseFloat($('budget-daily').value);
  if(d>=0) $('budget-weekly').value = Math.round(d*7);
}
function budgetWeeklyChanged(){
  var w = parseFloat($('budget-weekly').value);
  if(w>=0) $('budget-daily').value = Math.round(w/7);
}
function saveBudget(){
  var c = findCat(state.budgetSheetCat);
  var d = parseFloat($('budget-daily').value), w = parseFloat($('budget-weekly').value);
  if(c && d>=0 && w>=0){ c.daily=Math.round(d); c.weekly=Math.round(w); }
  closeSheet(); toast('Budget saved'); renderAll();
}
function renderSheetCats(){ renderChosenCats(); }

/* =====================================================================
   INSIGHTS
   ===================================================================== */
function weekdayTotals(){
  var out = [0,0,0,0,0,0,0], counts=[0,0,0,0,0,0,0];
  txnsSince(30).forEach(function(t){
    var d = new Date(t.ts).getDay();
    out[d]+=t.amt; counts[d]++;
  });
  return {totals:out, counts:counts};
}
function weekdayChart(){
  var wd = weekdayTotals();
  var vals = DAY_ORDER.map(function(d){ return wd.totals[d]; });
  var max = Math.max.apply(null, vals) || 1;
  var maxIdx = vals.indexOf(max);
  var W=316, H=118, n=7, gap=10;
  var bw = (W - gap*(n-1))/n;
  var html = '<svg viewBox="0 0 '+W+' '+(H+22)+'" width="100%" height="'+(H+22)+'">';
  vals.forEach(function(v,i){
    var h = Math.max(3, (v/max)*H);
    var x = i*(bw+gap), y = H-h;
    html += '<rect x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+bw.toFixed(1)
         +  '" height="'+h.toFixed(1)+'" rx="4" fill="'+(i===maxIdx?'#ff7a45':'#292929')+'"/>';
    html += '<text x="'+(x+bw/2).toFixed(1)+'" y="'+(H+15)+'" text-anchor="middle" '
         +  'font-size="10" fill="'+(i===maxIdx?'#ffffff':'#555555')+'">'
         +  DAY_NAMES[DAY_ORDER[i]] + '</text>';
  });
  html += '</svg>';
  return {html:html, max:max, maxDay:DAY_NAMES[DAY_ORDER[maxIdx]], vals:vals};
}
function biggestMover(){
  var best=null;
  CATS.forEach(function(c){
    var now = sum(byCat(txnsSince(7), c.name));
    var prev = sum(byCat(txnsBetween(13,6), c.name));
    if(prev < 150 || now < 100) return;
    var pct = Math.round(((now-prev)/prev)*100);
    if(!best || Math.abs(pct) > Math.abs(best.pct)) best={name:c.name, pct:pct, now:now, prev:prev};
  });
  return best;
}
function renderInsight(){
  var feed=$('insight-feed'); if(!feed) return;
  var cards=[];

  /* 1. budget pace — calendar week, Monday to today */
  var dayIdx = ((new Date().getDay()) + 6) % 7 + 1; /* Mon=1..Sun=7 */
  var calWeekSpent = sum(txnsSince(dayIdx));
  var weekSpent = sum(txnsSince(7));
  var weekBudget = CATS.reduce(function(a,c){ return a + c.weekly; },0);
  var expected = weekBudget * (dayIdx/7);
  var pacePct = weekBudget ? Math.min(100,(calWeekSpent/weekBudget)*100) : 0;
  var paceWord = calWeekSpent <= expected ? 'On track' : 'Ahead of pace';
  cards.push(
    '<button class="icard" onclick="go(\'categories\')">'
    + '<div class="ic-kicker">Budget pace</div>'
    + '<div class="ic-head">'+paceWord+' &mdash; '+money(calWeekSpent)+' of '+money(weekBudget)
    + ' since Monday</div>'
    + '<div class="ic-body"><div class="bar"><i style="width:'+pacePct.toFixed(1)+'%"></i></div></div>'
    + '<div class="ic-sub">Day '+dayIdx+' of 7. At a steady pace you would be around '
    + money(expected)+' by now.</div></button>');

  /* 2. day-of-week monthly spending */
  var wc = weekdayChart();
  cards.push(
    '<button class="icard" onclick="go(\'transactions\')">'
    + '<div class="ic-kicker">Day of the week &middot; last 30 days</div>'
    + '<div class="ic-head">'+wc.maxDay+' is your heaviest day</div>'
    + '<div class="ic-body">'+wc.html+'</div>'
    + '<div class="ic-sub">Totals for each weekday across the month. '
    + wc.maxDay+' adds up to '+money(wc.max)+'.</div></button>');

  /* 3. category trend */
  var mover = biggestMover();
  if(mover){
    cards.push(
      '<button class="icard" onclick="openCategory(\''+esc(mover.name)+'\')">'
      + '<div class="ic-kicker">Category trend</div>'
      + '<div class="ic-head">'+esc(mover.name)+' is '
      + (mover.pct>0 ? 'up '+mover.pct+'%' : 'down '+Math.abs(mover.pct)+'%')
      + ' vs last week</div>'
      + '<div class="ic-sub">'+money(mover.now)+' this week, against '+money(mover.prev)
      + ' the week before.</div></button>');
  }

  /* 4. accumulation spotlight */
  var pats = accumulationPatterns();
  if(pats.length){
    var p = pats[0];
    cards.push(
      '<button class="icard" onclick="openPattern(\''+esc(p.merchant)+'\')">'
      + '<div class="ic-kicker">Small purchases</div>'
      + '<div class="ic-head">'+esc(p.merchant)+': '+p.count+' visits = '+money(p.total)+'</div>'
      + '<div class="ic-sub">Each one was about '+money(p.total/p.count)
      + '. Small on its own, not small together.</div></button>');
  }

  /* 5. highest contributor */
  var rows = CATS.map(function(c){ return {name:c.name, amt:sum(byCat(txnsSince(30), c.name))}; })
                 .sort(function(a,b){ return b.amt-a.amt; });
  if(rows.length && rows[0].amt){
    var monthTotal = rows.reduce(function(a,r){ return a+r.amt; },0);
    var share = Math.round((rows[0].amt/monthTotal)*100);
    var others = monthTotal - rows[0].amt;
    cards.push(
      '<button class="icard" onclick="openCategory(\''+esc(rows[0].name)+'\')">'
      + '<div class="ic-kicker">Biggest contributor</div>'
      + '<div class="ic-head">'+esc(rows[0].name)+' takes '+share+'% of your month</div>'
      + '<div class="ic-body"><div class="bar"><i style="width:'+share+'%"></i></div></div>'
      + '<div class="ic-sub">'+money(rows[0].amt)+' on '+esc(rows[0].name)+', '+money(others)
      + ' across everything else.</div></button>');
  }

  /* 6. subscriptions */
  var subTotal = SUBS.reduce(function(a,s){ return a+s.amt; },0);
  if(SUBS.length){
    cards.push(
      '<button class="icard" onclick="go(\'savings\')">'
      + '<div class="ic-kicker">Recurring</div>'
      + '<div class="ic-head">'+money(subTotal)+' a month leaves on autopay</div>'
      + '<div class="ic-sub">'+SUBS.length+' subscriptions, '+money(subTotal*12)
      + ' a year. Next up: '+esc(nextDueSub().name)+'.</div></button>');
  }

  /* 7. savings goal */
  if(GOALS.length){
    var g = GOALS[0];
    var gp = Math.min(100,(g.saved/g.target)*100);
    cards.push(
      '<button class="icard" onclick="openGoal('+g.id+')">'
      + '<div class="ic-kicker">Savings goal</div>'
      + '<div class="ic-head">'+esc(g.name)+' is '+Math.round(gp)+'% funded</div>'
      + '<div class="ic-body"><div class="bar"><i style="width:'+gp.toFixed(1)+'%"></i></div></div>'
      + '<div class="ic-sub">'+money(g.saved)+' of '+money(g.target)+' saved'
      + (g.by ? ', aiming for '+esc(g.by) : '')+'.</div></button>');
  }

  /* 8. week over week */
  var prevWeek = sum(txnsBetween(13,6));
  if(prevWeek){
    var diff = weekSpent - prevWeek;
    var dpct = Math.round((diff/prevWeek)*100);
    cards.push(
      '<button class="icard" onclick="go(\'transactions\')">'
      + '<div class="ic-kicker">Week on week</div>'
      + '<div class="ic-head">'
      + (diff>=0 ? money(diff)+' more than last week' : money(-diff)+' less than last week')
      + '</div>'
      + '<div class="ic-sub">'+money(weekSpent)+' this week vs '+money(prevWeek)
      + ' last week &mdash; a '+Math.abs(dpct)+'% '+(diff>=0?'rise':'drop')+'.</div></button>');
  }

  feed.innerHTML = cards.join('');
}

/* =====================================================================
   SAVINGS TAB
   ===================================================================== */
function nextDueDate(day){
  var now = new Date(), d = new Date(now.getFullYear(), now.getMonth(), day);
  if(d < dayStart(now)) d = new Date(now.getFullYear(), now.getMonth()+1, day);
  return d;
}
function daysUntil(d){
  return Math.round((dayStart(d) - dayStart(new Date()))/86400000);
}
function nextDueSub(){
  var sorted = SUBS.slice().sort(function(a,b){
    return daysUntil(nextDueDate(a.day)) - daysUntil(nextDueDate(b.day));
  });
  return sorted[0] || {name:'—'};
}
function renderSavings(){
  var box=$('goal-list');
  if(box){
    box.innerHTML = GOALS.length ? GOALS.map(function(g){
      var pct = Math.min(100,(g.saved/g.target)*100);
      return '<button class="goal-card" onclick="openGoal('+g.id+')">'
        + '<div class="between"><span style="font-weight:700">'+esc(g.name)+'</span>'
        + '<span style="font-size:12px;color:var(--ink2)">'+Math.round(pct)+'%</span></div>'
        + '<div class="bar" style="margin-top:10px"><i style="width:'+pct.toFixed(1)+'%"></i></div>'
        + '<div class="between" style="margin-top:7px">'
        + '<span class="micro">'+money(g.saved)+' of '+money(g.target)+'</span>'
        + '<span class="micro">'+(g.by ? 'by '+esc(g.by) : '')+'</span></div>'
        + '</button>';
    }).join('') : '<p class="empty-note">No goals yet. A goal makes saving feel like progress, not restriction.</p>';
  }

  var subTotal = SUBS.reduce(function(a,s){ return a+s.amt; },0);
  var summ=$('sub-summary');
  if(summ) summ.textContent = SUBS.length
    ? money(subTotal) + ' a month on autopay — ' + money(subTotal*12) + ' a year.'
    : 'Nothing recurring yet.';

  var sl=$('sub-list');
  if(sl){
    var sorted = SUBS.slice().sort(function(a,b){
      return daysUntil(nextDueDate(a.day)) - daysUntil(nextDueDate(b.day));
    });
    sl.innerHTML = sorted.length ? sorted.map(function(s){
      var d = nextDueDate(s.day), n = daysUntil(d);
      var due = n===0 ? 'Due today' : n===1 ? 'Due tomorrow' : 'Due in '+n+' days';
      return '<button class="sub-row" onclick="openSub('+s.id+')">'
        + '<span class="rl-main"><span>'+esc(s.name)+'</span>'
        + '<span class="sr-due">'+due+' &middot; '+fmtDateShort(d)+'</span></span>'
        + '<span class="rl-val">'+money(s.amt)+'</span></button>';
    }).join('') : '<p class="empty-note">No subscriptions tracked.</p>';
  }
}
function fmtDateShort(d){
  return d.getDate()+' '+['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][d.getMonth()];
}
function submitGoal(){
  var n=$('gc-name').value.trim(), t=parseFloat($('gc-target').value), by=$('gc-by').value.trim();
  if(!n || !(t>0)){ showErr('err-gc'); return; }
  var id = GOALS.length ? Math.max.apply(null,GOALS.map(function(g){return g.id;}))+1 : 1;
  GOALS.push({id:id,name:n,target:Math.round(t),saved:0,by:by,hist:[]});
  $('gc-name').value=''; $('gc-target').value=''; $('gc-by').value='';
  hideErr('err-gc'); toast('Goal created'); go('savings');
}
function openGoal(id){ state.selectedGoal=id; go('goalDetail'); }
function renderGoalDetail(){
  var g = GOALS.filter(function(x){ return x.id===state.selectedGoal; })[0];
  if(!g) return;
  var pct = Math.min(100,(g.saved/g.target)*100);
  $('gd-title').textContent = g.name;
  $('gd-saved').textContent = money(g.saved);
  $('gd-of').textContent = 'of ' + money(g.target) + ' target';
  $('gd-fill').style.width = pct.toFixed(1)+'%';
  $('gd-pct').textContent = Math.round(pct)+'% there';
  $('gd-by').textContent = g.by ? 'by ' + g.by : '';
  $('gd-hist').innerHTML = g.hist.length ? g.hist.map(function(h){
    return '<div class="txn-row" style="cursor:default"><span class="t-merch">'+fmtDate(h.ts)+'</span>'
      + '<span class="t-cat">added</span><span class="t-amt">'+money(h.amt)+'</span></div>';
  }).join('') : '<p class="empty-note">Nothing added yet.</p>';
}
function contributeGoal(){
  var g = GOALS.filter(function(x){ return x.id===state.selectedGoal; })[0];
  var amt = parseFloat($('gd-add').value);
  if(!g || !(amt>0)){ showErr('err-gd'); return; }
  amt = Math.round(amt);
  g.saved += amt;
  g.hist.unshift({amt:amt, ts:Date.now()});
  state.balance = Math.max(0, state.balance - amt);
  $('gd-add').value=''; hideErr('err-gd');
  if(g.saved >= g.target){
    $('gr-line').textContent = g.name + ' is fully funded at ' + money(g.target) + '.';
    go('goalReached');
  } else {
    toast(money(amt) + ' added');
    renderAll();
  }
}
function openSub(id){ state.selectedSub=id; go('subDetail'); }
function renderSubDetail(){
  var s = SUBS.filter(function(x){ return x.id===state.selectedSub; })[0];
  if(!s) return;
  var d = nextDueDate(s.day), n = daysUntil(d);
  $('sd-title').textContent = s.name;
  $('sd-amt').textContent = money(s.amt);
  $('sd-cycle').textContent = 'Monthly, day ' + s.day;
  $('sd-due').textContent = fmtDateShort(d) + ' (' + (n===0?'today':'in '+n+' days') + ')';
  $('sd-cat').textContent = s.cat;
  $('sd-year').textContent = money(s.amt*12);
  $('sd-note').textContent = s.note ||
    ('That is ' + money(s.amt*12) + ' a year. Worth a check that you still use it.');
}
function removeSub(){
  SUBS = SUBS.filter(function(x){ return x.id!==state.selectedSub; });
  toast('Removed'); go('savings');
}
function submitSub(){
  var n=$('sa-name').value.trim(), a=parseFloat($('sa-amt').value), d=parseInt($('sa-day').value,10);
  if(!n || !(a>0) || !(d>=1 && d<=28)){ showErr('err-sa'); return; }
  var id = SUBS.length ? Math.max.apply(null,SUBS.map(function(s){return s.id;}))+1 : 1;
  SUBS.push({id:id,name:n,amt:Math.round(a),day:d,cat:'Necessities',note:''});
  $('sa-name').value=''; $('sa-amt').value=''; $('sa-day').value='';
  hideErr('err-sa'); toast('Subscription added'); go('savings');
}

/* =====================================================================
   SETTINGS
   ===================================================================== */
function renderTrackingSheet(){
  var u=$('track-tick-upi'), m=$('track-tick-manual');
  if(u) u.innerHTML = state.tracking!=='manual' ? '&#10003;' : '';
  if(m) m.innerHTML = state.tracking==='manual' ? '&#10003;' : '';
}
function setTracking(mode){
  state.tracking = mode;
  closeSheet(); renderAll();
  toast(mode==='upi' ? 'UPI auto-tracking on' : 'Manual entry only');
}
function setThreshold(p){ state.alertThreshold=p; renderAlerts(); }
function renderAlerts(){
  var box=$('alert-thresholds');
  if(box){
    box.innerHTML = [60,70,80,90,100].map(function(p){
      return '<button class="pill'+(state.alertThreshold===p?' on':'')
           + '" onclick="setThreshold('+p+')">'+p+'%</button>';
    }).join('');
  }
  var prev=$('alert-preview');
  if(prev){
    var c = CATS[0] ? CATS[0].name : 'Food';
    prev.textContent = 'You are at ' + state.alertThreshold + '% of your ' + c
      + ' budget for the week. ' + (state.perms['alert-daily']
        ? 'Recap tonight at 9pm.' : 'No daily recap.');
  }
}
function renderSettings(){
  var s=$('set-acct-sub');
  if(s) s.textContent = (ACCOUNTS[0] || 'Manual entry') + ' · PIN ' + (state.pin ? 'set' : 'not set');
  var a=$('set-acct-count'); if(a) a.textContent = ACCOUNTS.length;
  var t=$('set-tracking'); if(t) t.textContent = state.tracking==='manual' ? 'Manual' : 'UPI';
  var c=$('set-cat-count'); if(c) c.textContent = CATS.length;
  var al=$('set-alert-val'); if(al) al.textContent = state.alertThreshold + '%';
  var tx=$('set-txn-count'); if(tx) tx.textContent = TXNS.length;
  var pv=$('set-perm-val');
  if(pv){
    var on = ['perm-notif','perm-contacts','perm-camera']
      .filter(function(k){ return state.perms[k]; }).length;
    pv.textContent = on + ' on';
  }
}

/* =====================================================================
   MASTER RENDER
   ===================================================================== */
function renderAll(){
  renderUpiList();
  renderSheetAccounts();
  renderChosenCats();
  renderRecommended();
  renderPerms();
  renderAllSet();
  renderHome();
  renderAccumulation();
  renderAccumulationDetail();
  renderTxnList();
  renderTxnDetail();
  renderManualCats();
  renderContacts();
  renderPayCats();
  renderCategories();
  renderCategoryDetail();
  renderInsight();
  renderSavings();
  renderGoalDetail();
  renderSubDetail();
  renderAlerts();
  renderSettings();
}

/* =====================================================================
   BOOT / RESTART
   ===================================================================== */
function restartProto(){
  state = freshState();
  ACCOUNTS = ['sample@oksbi','sample2@oksbi'];
  seedCategories();
  seedTransactions();
  seedGoals();
  seedSubs();
  ['upi-input','cat-input','rec-search','pin1','pin2','pc1','pc2','txn-search',
   'me-amount','me-merchant','contact-search','bank-acct','bank-ifsc','pay-amount',
   'gc-name','gc-target','gc-by','gd-add','sa-name','sa-amt','sa-day',
   'sheet-upi-input','sheet-cat-input'].forEach(function(id){
    var el=$(id); if(el) el.value='';
  });
  var logo=$('upi-logo-1'); if(logo) logo.src = UPI_LOGO;
  document.body.classList.remove('with-nav');
  go('splash');
}

restartProto();
